from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass

logger = BackgroundLogger.Instance()


class LogsRC(AdminBaseClass):
    """Alarms"""
    def __init__(self):
        super(LogsRC, self).__init__()

    def download_technical_logs_rc(self, **kwargs):
        path = kwargs.get('log_dir', './execution_logs')
        log_filename = kwargs.get('log_filename', 'tech_logs.log')
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')

        return self.factory.rcconnect.download_technical_logs(path, timeout=timeout, connection=connection,
                                                          log_filename=log_filename)

    def stop_collecting_logs_rc(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.stop_collecting_logs(timeout=timeout, connection=connection)

    def get_diagnostics_rc(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.get_diagnostics(timeout=timeout, connection=connection)